description.en:
Declare it the way you declare `keyPressed()`:

```js
function controlChange(cc, value, channel) {
  // a control moved
}
```

It hears every control, including the ones that are not a knob or a fader, such as the mod wheel and the pedals, which [`knobMoved()`](#knobMoved) never reports. The latest value of every controller number is also in [`OAVp5.cc`](#OAVp5.cc), so a sketch that only wants to look can read `OAVp5.cc[1]` in `draw()`.

description.zh:
用宣告 `keyPressed()` 的方式宣告它：

```js
function controlChange(cc, value, channel) {
  // 有一個控制動了
}
```

每個控制它都聽得到，包括不是旋鈕也不是推桿的那些，像調變輪和踏板，[`knobMoved()`](#knobMoved) 永遠不會回報它們。每個控制器號碼的最新值也放在 [`OAVp5.cc`](#OAVp5.cc)，所以只想看一眼的草圖可以在 `draw()` 裡讀 `OAVp5.cc[1]`。

examples.code:
let shown = 'move a knob, the mod wheel or a pedal';

function setup() {
  createCanvas(400, 300);
  textAlign(CENTER, CENTER);
  textSize(24);
}

function controlChange(cc, value, channel) {
  shown = 'CC ' + cc + ' = ' + nf(value, 1, 2) + '  (channel ' + channel + ')';
}

function draw() {
  background(20);
  fill(255);
  text(shown, width / 2, height / 2);
}

let sustain = false;

function setup() {
  createCanvas(400, 300);
}

function controlChange(cc, value) {
  if (cc === 64) sustain = value >= 0.5;   // the sustain pedal: 64 and up counts as down
}

function mousePressed() {
  OAVp5.input([0xB0, 64, 127]);   // no pedal? press the mouse
}

function mouseReleased() {
  OAVp5.input([0xB0, 64, 0]);
}

function draw() {
  background(sustain ? 90 : 20);
}

function setup() {
  createCanvas(400, 300);
}

function draw() {
  background(20);
  fill(255);
  for (let i = 1; i <= 4; i++) circle(i * 80, height - 40 - fader(i) * 200, 30);
}

function setup() {
  createCanvas(400, 300);
}

function draw() {
  background(20);
  fill(255);
  rect(40, height - 40, fader1 * (width - 80), 24);   // fader 1 is a level bar
}

let level = 0;

function setup() {
  createCanvas(400, 300);
}

function faderMoved(n, value) {
  if (n === 1) level = value;   // fader 1 only
}

function draw() {
  background(20);
  fill(255);
  rect(40, height - 40, level * (width - 80), 24);
}

function setup() {
  createCanvas(400, 300);
  noStroke();
}

function draw() {
  background(20);
  fill(255);
  for (let i = 1; i <= 8; i++) {
    rect(i * 44 - 20, height - 20, 30, -10 - knob(i) * 250);   // one bar per knob
  }
}

function setup() {
  createCanvas(400, 300);
}

function draw() {
  background(knob1 * 255);   // knob 1 sets the brightness
}

function setup() {
  createCanvas(400, 300);
  colorMode(HSB, 1);
}

function draw() {
  background(0.65, 0.5, 0.15);
  fill(knob2, 0.8, 1);                        // knob 2: colour
  circle(width / 2, height / 2, 40 + knob1 * 300);   // knob 1: size
}

description.en:
Like `mouseMoved()` for knobs:

```js
function knobMoved(n, value) {
  // knob n is now at value
}
```

It is called for every step the knob sends, so many times per second while it turns. To read a knob once a frame, use [`knob1`](#knob1) instead.

description.zh:
就像旋鈕版的 `mouseMoved()`：

```js
function knobMoved(n, value) {
  // 旋鈕 n 現在在 value
}
```

旋鈕每送出一格就呼叫一次，轉動的時候每秒會呼叫很多次。想要每個畫面讀一次，就改用 [`knob1`](#knob1)。

examples.code:
let last = 'turn a knob';

function setup() {
  createCanvas(400, 300);
  textAlign(CENTER, CENTER);
  textSize(32);
}

function knobMoved(n, value) {
  last = 'knob ' + n + ': ' + nf(value, 1, 2);
}

function draw() {
  background(20);
  fill(255);
  text(last, width / 2, height / 2);
}

description.en:
Declare it the way you declare `keyPressed()`:

```js
function midiMessage(bytes, source) {
  // anything that came in
}
```

It is the widest net: it is called first for every note, control change and pitch bend, and it is the only function that hears the messages oav-p5 has no friendlier name for, such as channel pressure (`0xD0`), polyphonic aftertouch (`0xA0`) and program change (`0xC0`). The `OAVp5.last` object keeps the latest note, control change or pitch bend, but not those.

description.zh:
用宣告 `keyPressed()` 的方式宣告它：

```js
function midiMessage(bytes, source) {
  // 任何進來的訊息
}
```

它是網子最大的一個：每個音符、控制變化、音高輪訊息都會先呼叫它，而且 oav-p5 沒有比較親切的名字可以叫的訊息，只有它聽得到，像是通道壓力（`0xD0`）、各鍵觸後（`0xA0`）、音色切換（`0xC0`）。`OAVp5.last` 只留最新的音符、控制變化或音高輪，不留這些。

examples.code:
let shown = 'play something';

function setup() {
  createCanvas(400, 300);
  textAlign(CENTER, CENTER);
  textSize(20);
}

function midiMessage(bytes, source) {
  shown = bytes.map((b) => '0x' + b.toString(16).toUpperCase()).join(' ') + '  from ' + source;
}

function draw() {
  background(20);
  fill(255);
  text(shown, width / 2, height / 2);
}

let pressure = 0;

function setup() {
  createCanvas(400, 300);
}

function midiMessage(bytes) {
  if ((bytes[0] & 0xF0) === 0xD0) pressure = bytes[1] / 127;   // channel pressure (aftertouch)
}

function mouseMoved() {
  OAVp5.input([0xD0, constrain(round(mouseX / width * 127), 0, 127)], 'mouse');   // no aftertouch? move the mouse
}

function draw() {
  background(20);
  circle(width / 2, height / 2, 40 + pressure * 260);
}

function setup() {
  createCanvas(400, 300);
  textAlign(CENTER, CENTER);
  textSize(64);
}

function draw() {
  background(20);
  fill(255);
  text(noteName(note), width / 2, height / 2);   // the last key, as a name
}

function setup() {
  createCanvas(400, 300);
}

function draw() {
  background(20);
  fill(noteIsDown('C4') ? color(255, 211, 107) : 80);
  circle(width / 2, height / 2, 140);   // lights up while middle C is held
}

function setup() {
  createCanvas(400, 300);
}

function draw() {
  background(noteIsPressed ? 90 : 20);   // lighter while any key is down
}

description.en:
The partner of [`noteOn()`](#noteOn):

```js
function noteOff(note, channel) {
  // a key or pad came up
}
```

It is called for a note-off message and also for a note-on with velocity 0, which many keyboards send instead. There is no velocity: oav-p5 does not pass the release velocity.

description.zh:
[`noteOn()`](#noteOn) 的另一半：

```js
function noteOff(note, channel) {
  // 有一個鍵或打擊墊放開了
}
```

note-off 訊息會呼叫它，力道是 0 的 note-on 也會（很多鍵盤用那個來代替 note-off）。沒有力道這個參數：oav-p5 不傳放開時的力道。

examples.code:
const down = {};
let held = 'play a key and let it go';

function setup() {
  createCanvas(400, 300);
  textAlign(CENTER, CENTER);
  textSize(24);
}

function noteOn(note) { down[note] = millis(); }

function noteOff(note) {
  if (down[note] !== undefined) {
    held = noteName(note) + ' was held ' + round(millis() - down[note]) + ' ms';
    delete down[note];
  }
}

function draw() {
  background(20);
  fill(255);
  text(held, width / 2, height / 2);
}

description.en:
Declare it the way you declare `keyPressed()`:

```js
function noteOn(note, velocity, channel) {
  // a key or pad went down
}
```

It is called once per note-on message, as it came in. It is the level below [`notePressed()`](#notePressed): the same moment, but with the channel, and for pads too, even when the sketch defines [`padPressed()`](#padPressed). A note-on with velocity 0, which some keyboards send instead of a note-off, is not a note-on here: it calls [`noteOff()`](#noteOff).

description.zh:
用宣告 `keyPressed()` 的方式宣告它：

```js
function noteOn(note, velocity, channel) {
  // 有一個鍵或打擊墊按下去了
}
```

每則 note-on 訊息進來就呼叫一次，照它進來的樣子。它比 [`notePressed()`](#notePressed) 低一層：同一個時刻，但多了通道，而且打擊墊也會呼叫，就算草圖有定義 [`padPressed()`](#padPressed) 也一樣。力道是 0 的 note-on（有些鍵盤用它來代替 note-off）在這裡不算 note-on，會去呼叫 [`noteOff()`](#noteOff)。

examples.code:
let shown = 'play a key';

function setup() {
  createCanvas(400, 300);
  textAlign(CENTER, CENTER);
  textSize(24);
}

function noteOn(note, velocity, channel) {
  shown = noteName(note) + '  velocity ' + nf(velocity, 1, 2) + '  channel ' + channel;
}

function draw() {
  background(20);
  fill(255);
  text(shown, width / 2, height / 2);
}

let hits = [];

function setup() {
  createCanvas(400, 300);
  noStroke();
}

function noteOn(note, velocity, channel) {
  hits.push({ note, velocity, pad: channel === 10, born: millis() });   // channel 10: the pads
}

function draw() {
  background(20);
  hits = hits.filter((h) => millis() - h.born < 1500);
  for (const h of hits) {
    const fade = 1 - (millis() - h.born) / 1500;
    const x = map(h.note, 24, 96, 20, width - 20);
    fill(h.pad ? color(255, 90, 31, fade * 255) : color(120, 190, 255, fade * 255));
    if (h.pad) square(x - 25, 125, 50 + h.velocity * 40);
    else circle(x, 150, 20 + h.velocity * 80);
  }
}

description.en:
Declare it the way you declare `keyPressed()`:

```js
function notePressed(note, velocity) {
  // a key went down
}
```

It is called once per key, with the key and how hard. A pad also calls it, unless the sketch defines [`padPressed()`](#padPressed).

description.zh:
用宣告 `keyPressed()` 的方式宣告它：

```js
function notePressed(note, velocity) {
  // 有一個鍵按下去了
}
```

每個鍵呼叫一次，帶著是哪個鍵、多用力。打擊墊也會呼叫它，除非草圖有定義 [`padPressed()`](#padPressed)。

examples.code:
function setup() {
  createCanvas(400, 300);
  background(20);
  noStroke();
}

function notePressed(note, velocity) {
  fill(random(255), random(255), random(255), 200);
  circle(map(note, 36, 96, 20, width - 20), height / 2, 10 + velocity * 120);
}

description.en:
The partner of [`notePressed()`](#notePressed), like `keyReleased()` to `keyPressed()`:

```js
function noteReleased(note) {
  // a key came up
}
```

description.zh:
[`notePressed()`](#notePressed) 的另一半，就像 `keyReleased()` 之於 `keyPressed()`：

```js
function noteReleased(note) {
  // 有一個鍵放開了
}
```

examples.code:
let held = {};

function setup() {
  createCanvas(400, 300);
}

function notePressed(note) { held[note] = millis(); }
function noteReleased(note) { delete held[note]; }

function draw() {
  background(20);
  fill(255);
  text(Object.keys(held).map((n) => noteName(+n)).join('  '), 20, 40);   // the keys down now
}

function setup() {
  createCanvas(400, 300);
  noStroke();
}

function draw() {
  background(20);
  for (let i = 1; i <= 8; i++) {
    fill(255, 90, 31, 60 + pad(i) * 195);
    square(20 + ((i - 1) % 4) * 92, 40 + floor((i - 1) / 4) * 110, 80);
  }
}

function setup() {
  createCanvas(400, 300);
}

function draw() {
  background(20);
  fill(255, 90, 31);
  circle(width / 2, height / 2, 40 + pad1 * 260);   // swells while pad 1 is held
}

description.en:
```js
function padPressed(n, velocity) {
  // pad n was hit
}
```

When the sketch defines `padPressed()`, a pad calls it and **not** [`notePressed()`](#notePressed); without it, a pad calls `notePressed()` like any key.

description.zh:
```js
function padPressed(n, velocity) {
  // 墊子 n 被打了一下
}
```

草圖有定義 `padPressed()` 的話，打擊墊會呼叫它，而**不會**呼叫 [`notePressed()`](#notePressed)。沒有定義的話，打擊墊會像任何一個鍵一樣呼叫 `notePressed()`。

examples.code:
let hits = [];

function setup() {
  createCanvas(400, 300);
  noStroke();
}

function padPressed(n, velocity) {
  hits.push({ x: 40 + ((n - 1) % 4) * 105, y: 70 + floor((n - 1) / 4) * 130, r: 20 + velocity * 60 });
}

function draw() {
  background(20, 40);
  fill(255, 90, 31);
  for (const h of hits) { circle(h.x, h.y, h.r); h.r *= 0.95; }
  hits = hits.filter((h) => h.r > 2);
}

let down = {};

function setup() {
  createCanvas(400, 300);
}

function padPressed(n) { down[n] = true; }
function padReleased(n) { down[n] = false; }

function draw() {
  background(20);
  fill(255, 90, 31);
  for (let i = 1; i <= 8; i++) if (down[i]) square(10 + (i - 1) * 48, 130, 40);   // lit while held
}

description.en:
Declare it the way you declare `keyPressed()`:

```js
function pitchBend(value, channel) {
  // the wheel moved
}
```

A pitch wheel usually springs back to the middle when you let go, so you will hear a stream of values ending at 0. MIDI sends the position as 14 bits (0 to 16383, with 8192 in the middle). oav-p5 hands it to you as −1 to 1. The latest position is also in [`OAVp5.bend`](#OAVp5.bend).

description.zh:
用宣告 `keyPressed()` 的方式宣告它：

```js
function pitchBend(value, channel) {
  // 輪子動了
}
```

音高輪放開之後通常會自己彈回中間，所以你會收到一串值，最後停在 0。MIDI 用 14 位元送出位置（0 到 16383，中間是 8192），oav-p5 轉成 −1 到 1 給你。最新的位置也放在 [`OAVp5.bend`](#OAVp5.bend)。

examples.code:
let bend = 0;

function setup() {
  createCanvas(400, 300);
}

function pitchBend(value) {
  bend = value;
}

function draw() {
  background(20);
  circle(width / 2 + bend * 150, height / 2, 50);   // wheel up: right, wheel down: left
}

let bend = 0;

function setup() {
  createCanvas(400, 300);
}

function pitchBend(value) { bend = value; }

function mouseDragged() {
  OAVp5.input([0xE0, 0, constrain(round(mouseX / width * 127), 0, 127)]);   // no wheel? drag the mouse
}

function draw() {
  background(20);
  const x = spring(width / 2 + bend * 150, 120, 8);   // a spring smooths the steps
  circle(x, height / 2, 50);
}

function setup() {
  createCanvas(400, 300);
}

function draw() {
  background(20);
  fill(255, 90, 31);
  circle(width / 2, height / 2, 20 + velocity * 300);   // a harder key makes a bigger circle
}

function setup() {
  createCanvas(400, 300);
}

function mouseDragged() {
  OAVp5.input([0xE0, 0, constrain(round(mouseX / width * 127), 0, 127)]);   // no wheel? drag the mouse
}

function draw() {
  background(20);
  circle(width / 2 + OAVp5.bend * 150, height / 2, 50);   // wheel up: right, wheel down: left
  text('bend ' + nf(OAVp5.bend, 1, 2), 20, 30);
}

function setup() {
  createCanvas(400, 300);
}

